actual_contract_annotation:
#[cfg_attr(kani,kani::modifies(Rc::as_ptr(&self.data).cast_mut().cast::<isize>()))]
#[cfg_attr(kani,kani::ensures(|result| {
    let before=old(unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()});let now=unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()};
    match result {
        Ok(n)=>before>=0 && before<isize::MAX && *n==unsafe{(&*self.data.as_ptr()).len()} && now==before,
        Err(e)=>matches!(e,ProgramError::AccountBorrowFailed) && (before<0 || before==isize::MAX) && now==before,
    }
}))]

